function buildDay31To60(t: (typeof DAYS_31_TO_60_TOPICS)[number]): ChallengeDay {
  const baseWords = DOMAIN_LEXICONS[t.domain];
  // Rotate word order deterministically so each day highlights distinct lead words in its quiz & essays while staying 100% inside the exact topic domain
  const offset = (t.day * 3) % baseWords.length;
  const rotatedWords: WordTuple[] = [
    ...baseWords.slice(offset),
    ...baseWords.slice(0, offset)
  ];
  const w0 = rotatedWords[0];
  const w1 = rotatedWords[1];
  const w2 = rotatedWords[2];
  const w3 = rotatedWords[3];

  const seed: RichTopicSeed = {
    day: t.day,
    themeVi: t.themeVi,
    themeEn: t.themeEn,
    description: t.desc,
    words: rotatedWords,
    readingTitle: t.rTitle,
    readingHookEn: `In contemporary discussions surrounding ${t.themeEn.toLowerCase()}, policymakers and citizens alike are re-evaluating how daily habits and institutional frameworks shape long-term societal well-being. ${w0[7]}`,
    readingHookVi: `Trong các cuộc thảo luận đương đại xoay quanh chủ đề ${t.themeVi.toLowerCase()}, cả các nhà hoạch định chính sách lẫn người dân đều đang nhìn nhận lại cách những thói quen hằng ngày và khung thể chế định hình phúc lợi xã hội lâu dài. ${w0[8]}`,
    readingBodyEn: `Empirical evidence demonstrates that sustainable progress cannot rely on superficial measures alone. ${w1[7]} Furthermore, ${w2[7]} When schools, families, and enterprises actively champion "${w3[4]}", communities achieve measurable improvements in both productivity and quality of life.`,
    readingBodyVi: `Các bằng chứng thực tế chứng minh rằng sự tiến bộ bền vững không thể chỉ dựa vào những biện pháp bề nổi. ${w1[8]} Hơn thế nữa, ${w2[8]} Khi nhà trường, gia đình và doanh nghiệp chủ động thúc đẩy "${w3[4]}" (${w3[3]}), cộng đồng sẽ đạt được những cải thiện rõ rệt cả về hiệu suất lẫn chất lượng sống.`,
    readingConclusionEn: `Ultimately, addressing the complexities of ${t.themeEn.toLowerCase()} requires a balanced synthesis of personal responsibility and forward-looking policy.`,
    readingConclusionVi: `Sau cùng, việc giải quyết thấu đáo các khía cạnh của ${t.themeVi.toLowerCase()} đòi hỏi sự kết hợp hài hòa giữa trách nhiệm cá nhân và chính sách có tầm nhìn xa.`,
    questionType: t.wType,
    wPromptEn: t.wPromptEn,
    wPromptVi: t.wPromptVi,
    wIntroOutline: `Paraphrase đề bài về chủ đề ${t.themeVi}. Nêu Thesis Statement rõ ràng: Cần kết hợp đồng bộ giữa ý thức tự giác của cá nhân và giải pháp thiết thực từ nhà trường, gia đình, xã hội.`,
    wBody1Outline: `Phân tích luận điểm trọng tâm thứ nhất gắn với thực tiễn: Vận dụng từ vựng "${w0[0]}" (${w0[3]}) và "${w1[0]}" (${w1[3]}) kèm dẫn chứng thực tế.`,
    wBody2Outline: `Phân tích luận điểm thứ hai và đề xuất giải pháp bền vững: Sử dụng cụm "${w2[4]}" và "${w3[4]}" để làm sâu sắc lập luận phản biện.`,
    wConclusionOutline: `Tóm tắt lại toàn bộ luận điểm và khẳng định tầm nhìn dài hạn đối với ${t.themeVi.toLowerCase()}.`,
    wCoreArgument1En: `Addressing ${t.themeEn.toLowerCase()} effectively requires proactive education and evidence-based policies that empower individuals.`,
    wCoreArgument1Vi: `Giải quyết hiệu quả vấn đề ${t.themeVi.toLowerCase()} đòi hỏi sự giáo dục chủ động và các chính sách thực tiễn nhằm trao quyền cho mỗi cá nhân.`,
    wCoreArgument2En: `Ignoring the long-term impacts of this issue can erode community well-being unless institutions and citizens act together.`,
    wCoreArgument2Vi: `Việc phớt lờ những tác động dài hạn của vấn đề này có thể làm suy giảm phúc lợi cộng đồng trừ khi các tổ chức và người dân cùng chung tay hành động.`,
    sTopic1En: t.themeEn.split(',')[0].trim(),
    sTopic1Vi: t.themeVi.split(',')[0].trim(),
    sTopic2En: t.themeEn.split(',')[1]?.trim() || 'Community & Future Trends',
    sTopic2Vi: t.themeVi.split(',')[1]?.trim() || 'Cộng đồng & Xu hướng tương lai',
    sPart1Q1En: `How does ${t.themeEn.split(',')[0].trim().toLowerCase()} affect your daily life or studies?`,
    sPart1Q1Vi: `${t.themeVi.split(',')[0].trim()} ảnh hưởng như thế nào đến cuộc sống hoặc việc học hằng ngày của bạn?`,
    sPart1Q2En: `Do people in your city pay enough attention to ${t.themeEn.split(',')[0].trim().toLowerCase()} nowadays?`,
    sPart1Q2Vi: `Người dân ở thành phố của bạn ngày nay đã quan tâm đúng mức đến ${t.themeVi.split(',')[0].trim().toLowerCase()} chưa?`,
    sPart1Q3En: `What is one positive habit you have formed regarding this topic?`,
    sPart1Q3Vi: `Một thói quen tích cực mà bạn đã hình thành liên quan đến chủ đề này là gì?`,
    sPart2Q1En: `Why is ${t.themeEn.split(',')[1]?.trim().toLowerCase() || 'this topic'} becoming increasingly important in modern society?`,
    sPart2Q1Vi: `Tại sao ${t.themeVi.split(',')[1]?.trim().toLowerCase() || 'chủ đề này'} ngày càng trở nên quan trọng trong xã hội hiện đại?`,
    sPart2Q2En: `What role should schools and families play in educating young people about this issue?`,
    sPart2Q2Vi: `Nhà trường và gia đình nên đóng vai trò gì trong việc định hướng cho người trẻ về vấn đề này?`,
    sPart2Q3En: `What positive changes do you hope to see in this area over the next five years?`,
    sPart2Q3Vi: `Bạn hy vọng sẽ thấy những thay đổi tích cực nào trong lĩnh vực này vào 5 năm tới?`,
    sSituationEn: t.sSitEn,
    sSituationVi: t.sSitVi,
    sOptionATitle: t.optA[0],
    sOptionADescVi: t.optA[1],
    sOptionAProsVi: t.optA[2],
    sOptionAConsVi: t.optA[3],
    sOptionBTitle: t.optB[0],
    sOptionBDescVi: t.optB[1],
    sOptionBProsVi: t.optB[2],
    sOptionBConsVi: t.optB[3],
    sOptionCTitle: t.optC[0],
    sOptionCDescVi: t.optC[1],
    sOptionCProsVi: t.optC[2],
    sOptionCConsVi: t.optC[3]
  };

  // If Option A is the clearly superior option in this scenario (where optA[2] is long and detailed), swap Option A & B so Option B is always the canonical chosen option in the builder, or update part2Samples to match the best option
  const isOptionABest = t.optA[2].length > t.optB[2].length;
  if (isOptionABest) {
    seed.sOptionATitle = t.optB[0].replace('Option B:', 'Option A:');
    seed.sOptionADescVi = t.optB[1];
    seed.sOptionAProsVi = t.optB[2];
    seed.sOptionAConsVi = t.optB[3];
    seed.sOptionBTitle = t.optA[0].replace('Option A:', 'Option B:');
    seed.sOptionBDescVi = t.optA[1];
    seed.sOptionBProsVi = t.optA[2];
    seed.sOptionBConsVi = t.optA[3];
  }

  return buildDayFromRichSeed(seed);
}

export const DAYS_16_TO_60: ChallengeDay[] = [
  ...SPECIFIC_DAYS_16_TO_30.map(buildDay16To30),
  ...DAYS_31_TO_60_TOPICS.map(buildDay31To60)
];
